mapper.select:
SELECT d.*, t.name AS tenant_name
FROM sys_dept d
LEFT JOIN sys_tenant t ON t.id = d.tenant_id AND t.is_deleted = 0
WHERE d.is_deleted = 0
AND d.tenant_id = #{tenantId}

    AND d.parent_id = #{request.parentId}


    AND (d.name LIKE CONCAT('%', #{request.keyword}, '%')
         OR d.code LIKE CONCAT('%', #{request.keyword}, '%'))


    AND d.status = #{request.status}



        ORDER BY ${request.safeSortField()} ${request.safeSortOrder()}


        ORDER BY d.sort ASC
